---@class UINightCatIToweRewardNode
---@field Env                           	UINightCatIToweRewardNode                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field CommonGoodsList               	UnityEngine.RectTransform               
---@field TxtTitle                      	UnityEngine.RectTransform               
---@field ImgInk2                       	UnityEngine.RectTransform               
---@field ImgInk1                       	UnityEngine.RectTransform               
---@field Normal                        	UnityEngine.RectTransform                                             
local UINightCatIToweRewardNode = Class('UINightCatIToweRewardNode')

function UINightCatIToweRewardNode:__init()
    self._questId = nil
end

function UINightCatIToweRewardNode:__delete()
    self._questId = nil
end

function UINightCatIToweRewardNode:Awake()
    --SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTeamInfo))
end

---Refresh
---@param data table 
function UINightCatIToweRewardNode:Refresh(questId, isMe)
    if not questId then
        return
    end

    self._questId = questId

    self:FillSelf()
end

function UINightCatIToweRewardNode:FillSelf()
    local t = RewardConfMgr:GetInstance():GetQuestRewardData(self._questId, Constants.QuestRewardType.FristRewards)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    scr:FreshBaseUI(t, false)

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._questId)
    if vo then
        CfUtils.FillText(self.TxtTitle, localize("第_num_层奖励", {_num_ = vo.storey}))
    end

    local maxTowerId = comp:GetMaxPassTowerId()
    local maxVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)

    if maxVo then
        CfUtils.SetUISwitchImage(self.ImgInk1, checkNumber(maxVo.storey) >= checkNumber(vo.storey) and 2 or 1)
        CfUtils.SetUISwitchImage(self.ImgInk2, checkNumber(maxVo.storey) >= checkNumber(vo.storey) and 2 or 1)

        CfUtils.SetActive(self.controller.gameObject.transform:Find("CompleteNode"), checkNumber(maxVo.storey) >= checkNumber(vo.storey))
    else
        CfUtils.SetActive(self.controller.gameObject.transform:Find("CompleteNode"), false)
    end

end

function UINightCatIToweRewardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UINightCatIToweRewardNode
